mapper.select:
SELECT FROM EDU_PRGRM_INTRD P WHERE P.DEL_YN = 'N'
AND P.PRGRM_CTGRY_CD = #{prgrmCtgryCd}
AND P.USE_YN = #{useYn}
AND P.PRGRM_TTL LIKE CONCAT('%', #{keyword}, '%')
ORDER BY P.SORT_SEQ ASC, P.PRGRM_INTRD_SN ASC

mapper.insert:
INSERT INTO EDU_PRGRM_INTRD (
	PRGRM_CTGRY_CD, PRGRM_TTL, PRGRM_EXPLN, PLC_CN, OPRTN_PD_CN, NOPE_CN,
	APLY_URL_ADDR, IMG_FILE_ID, SORT_SEQ, USE_YN, DEL_YN, REG_DT, RGTR_NM, MDFCN_DT, MDFR_NM
) VALUES (
	#{prgrmCtgryCd}, #{prgrmTtl}, #{prgrmExpln}, #{plcCn}, #{oprtnPdCn}, #{nopeCn},
	#{aplyUrlAddr}, #{imgFileId}, #{sortSeq}, #{useYn}, 'N', NOW(), #{rgtr}, NOW(), #{mdtr}
)

mapper.update:
UPDATE EDU_PRGRM_INTRD
SET SORT_SEQ = #{sortSeq},
	MDFCN_DT = NOW(),
	MDFR_NM = #{mdtr}
WHERE PRGRM_INTRD_SN = #{prgrmIntrdSn}
	AND DEL_YN = 'N'

UPDATE EDU_PRGRM_INTRD
SET DEL_YN = 'Y',
	DEL_DT = NOW(),
	DLTR_NM = #{deltr}
WHERE PRGRM_INTRD_SN = #{prgrmIntrdSn}
	AND DEL_YN = 'N'
